import { useChromeStorageLocal } from 'hooks/chrome-storage-listener'
import { ReactNode, useEffect, useState } from 'react'
import { EXTENSION_TOUR_CACHE_NAME } from '../helper'
import * as S from './styles'

let timer: NodeJS.Timeout

interface ExtensionTourLayoutProps {
  children: ReactNode
}

function ExtensionTourLayout({ children }: ExtensionTourLayoutProps) {
  const { currentData } = useChromeStorageLocal(EXTENSION_TOUR_CACHE_NAME)
  const [active, setActive] = useState(false)

  useEffect(() => {
    clearTimeout(timer)
    if (currentData === undefined) {
      timer = setTimeout(() => {
        setActive(true)
      }, 500)
    } else {
      clearTimeout(timer)
      setActive(false)
    }
  }, [currentData])
  return (
    <>
      {active ? (
        <S.Main>
          <S.Content>{children}</S.Content>
        </S.Main>
      ) : null}
    </>
  )
}

export default ExtensionTourLayout
