import { useNavigate, useParams } from 'react-router'
import {
  EXTENSION_TOUR_CACHE_NAME,
  EXTENSION_TOUR_STATES,
  makeStepData,
} from 'scripts/extension-tour/helper'
import * as S from './styles'

function Step() {
  const { stepNumber } = useParams()
  const navigate = useNavigate()

  const stepData = makeStepData(stepNumber!)

  async function closeTour(state: string) {
    await chrome.storage.local.set({ [EXTENSION_TOUR_CACHE_NAME]: state })
  }

  return (
    <S.Main>
      <img
        src={stepData.imageUrl}
        alt='Reclame AQUI - Tour da extensão 1'
        useMap={`#${stepData.mapName}`}
      />

      <map name={stepData.mapName}>
        {stepData.dotsCoord?.map((coord, index) => (
          <S.Area
            shape='rect'
            coords={coord}
            alt={`Area pontos - ${stepNumber}`}
            onClick={() => {
              navigate(`/step/${index + 2}`)
            }}
          />
        ))}
        {stepData.coords.map((coord, index) => (
          <S.Area
            shape='rect'
            coords={coord}
            alt={`Area botões - ${stepNumber}`}
            onClick={() => {
              if (stepNumber === '7')
                return closeTour(EXTENSION_TOUR_STATES.finished)

              index > 0
                ? closeTour(EXTENSION_TOUR_STATES.skipped)
                : navigate(stepData.nextStep)
            }}
          />
        ))}
      </map>
    </S.Main>
  )
}

export default Step
