// eslint-disable-next-line @typescript-eslint/no-unused-vars
/*global chrome*/
import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import { MemoryRouter, Route, Routes } from 'react-router'
import shadowRoot from 'react-shadow/styled-components'

import Step from './components/Step'
import ExtensionTourLayout from './layout'

export function ExtensionTour() {
  return (
    <shadowRoot.section>
      <MemoryRouter initialEntries={['/step/1']}>
        <ExtensionTourLayout>
          <Routes>
            <Route path='step/:stepNumber' element={<Step />} />
          </Routes>
        </ExtensionTourLayout>
      </MemoryRouter>
    </shadowRoot.section>
  )
}

const extensionTourMainWrapper: HTMLElement = document.createElement(
  'reclameaqui-extension-tour'
)
document.body.appendChild(extensionTourMainWrapper)

const extensionRoot = document.getElementById('extension-root')

const reactRoot = createRoot(extensionTourMainWrapper!)

window.onload = function () {
  var bodyList: any = document.querySelector('body')

  var observer = new MutationObserver(function (mutations) {
    // eslint-disable-next-line @typescript-eslint/no-unused-expressions
    !extensionRoot && document.location.pathname === '/extensao/'
      ? reactRoot.render(
          <StrictMode>
            <ExtensionTour />
          </StrictMode>
        )
      : ''
  })

  var config = {
    childList: true,
    subtree: true,
  }

  observer.observe(bodyList, config)
}

!extensionRoot &&
  document.location.pathname === '/extensao/' &&
  reactRoot.render(
    <StrictMode>
      <ExtensionTour />
    </StrictMode>
  )
